#!/usr/bin/env python3
"""Generate lib/pkb_core/gen/* from pokecrystal at the pinned revision.

Outputs (committed; regenerating must produce no diff):
  pb_const.h     constants from the battle/move/item/pokemon/type/serial/text
                 constant files, with their pokecrystal names
  pb_tables.h    declarations for the tables below
  base_stats.c   pb_base_stats[]       stats, types, gender, growth rate
  moves.c        pb_moves[]            effect, power, type, accuracy, PP, chance
  names.c        species/move names and the names of items with a held
                 effect (Game Boy charset, packed)
  charmap.c      ASCII <-> Game Boy charset tables
  growth.c       pb_growth_rates[]     CalcExpAtLevel coefficients
  pb_wram.h, pb_battle.h, battle_tables.c   battle engine data (gen_battle.py)

Usage: python tools/gen/gen_tables.py [--check]
"""
import argparse
import pathlib
import re
import subprocess
import sys

import asmlib
import boss_items
import gen_battle
import legality

REPO = pathlib.Path(__file__).resolve().parents[2]
OUT = REPO / "lib" / "pkb_core" / "gen"

CONST_FILES = [
    "constants/text_constants.asm",
    "constants/battle_constants.asm",
    "constants/move_constants.asm",
    "constants/move_effect_constants.asm",
    "constants/item_constants.asm",
    "constants/item_data_constants.asm",
    "constants/pokemon_constants.asm",
    "constants/pokemon_data_constants.asm",
    "constants/type_constants.asm",
    "constants/serial_constants.asm",
    "constants/ram_constants.asm",
]
# assembler bookkeeping variables, not real constants
SKIP_SYMBOLS = {"HM_VALUE", "MT_VALUE"}
C_RESERVED = {"NULL", "TRUE", "FALSE", "EOF", "BUFSIZ", "MIN", "MAX"}


def header(data, what):
    return (
        f"/* GENERATED by tools/gen/{pathlib.Path(sys.argv[0]).name} from pret/pokecrystal "
        f"{data.sha} ({what}).\n * Do not edit; regenerate instead. */\n"
    )


def gen_const(data):
    a = data.asm
    lines = [
        header(data, ", ".join(pathlib.Path(f).name for f in CONST_FILES)),
        "#pragma once\n",
    ]
    by_file = {f: [] for f in CONST_FILES}
    for name, value in a.sym.items():
        f = a.def_file.get(name)
        if f not in by_file or name in SKIP_SYMBOLS or name in C_RESERVED:
            continue
        if not re.fullmatch(r"[A-Z][A-Z0-9_]*", name):
            continue
        by_file[f].append((name, value))
    for f in CONST_FILES:
        lines.append(f"\n/* {f} */")
        for name, value in by_file[f]:
            v = (
                f"({value})"
                if value < 0
                else (f"0x{value:02X}" if value > 9 else str(value))
            )
            lines.append(f"#define {name} {v}")
    return "\n".join(lines) + "\n"


TABLES_H = """\
#pragma once

#include <stdint.h>
#include "pb_const.h"

/* Index with species - 1. */
typedef struct {
    uint8_t stats[6]; /* hp, atk, def, spd, sat, sdf */
    uint8_t types[2];
    uint8_t gender; /* GENDER_*; 0xFF = GENDER_UNKNOWN */
    uint8_t growth_rate; /* GROWTH_* */
} PbBaseStats;
extern const PbBaseStats pb_base_stats[NUM_POKEMON];

/* Index with move - 1. The animation byte of the asm move struct always
 * equals the move id, so it is not stored. */
typedef struct {
    uint8_t effect;
    uint8_t power;
    uint8_t type;
    uint8_t accuracy;
    uint8_t pp;
    uint8_t effect_chance;
} PbMove;
extern const PbMove pb_moves[NUM_ATTACKS];

/* Packed names in the Game Boy charset, no terminators: name i (0-based)
 * spans [off[i], off[i + 1]). */
extern const uint8_t pb_species_names[];
extern const uint16_t pb_species_name_off[NUM_POKEMON + 1];
extern const uint8_t pb_move_names[];
extern const uint16_t pb_move_name_off[NUM_ATTACKS + 1];

/* ASCII -> Game Boy charset (0 = unmapped) and back ('?' = unmapped,
 * 0 for the '@' terminator). */
extern const uint8_t pb_ascii_to_gb[128];
extern const char pb_gb_to_ascii[256];

/* Item names (index item - 1), only for items with a held effect; the
 * others are empty. */
#define PB_ITEM_NAMES_LEN 255
extern const uint8_t pb_item_names[];
extern const uint16_t pb_item_name_off[PB_ITEM_NAMES_LEN + 1];

/* data/growth_rates.asm: exp(n) = a/b*n^3 + c*n^2 + d*n - e */
typedef struct {
    uint8_t a, b;
    int8_t c;
    uint8_t d, e;
} PbGrowthRate;
extern const PbGrowthRate pb_growth_rates[NUM_GROWTH_RATES];
"""


def c_bytes(bs, per_line=16, indent="    "):
    out = []
    for i in range(0, len(bs), per_line):
        out.append(indent + ", ".join(f"0x{b:02X}" for b in bs[i : i + per_line]) + ",")
    return "\n".join(out)


def gen_base_stats(data):
    s = [
        header(data, "data/pokemon/base_stats/<species>.asm"),
        '#include "pb_tables.h"\n',
        "const PbBaseStats pb_base_stats[NUM_POKEMON] = {",
    ]
    for sid, rec in enumerate(data.base, start=1):
        st = ", ".join(str(x) for x in rec["stats"])
        types = ", ".join(data.const_name("type", t) for t in rec["types"])
        gender = data.const_name("gender", rec["gender"])
        growth = data.const_name("growth", rec["growth_rate"])
        s.append(
            f"    {{{{{st}}}, {{{types}}}, {gender}, {growth}}}, /* {data.species[sid - 1]} */"
        )
    s.append("};")
    return "\n".join(s) + "\n"


def gen_moves(data):
    s = [
        header(data, "data/moves/moves.asm"),
        '#include "pb_tables.h"\n',
        "const PbMove pb_moves[NUM_ATTACKS] = {",
    ]
    for mid, m in enumerate(data.moves, start=1):
        eff = data.const_name("effect", m["effect"])
        typ = data.const_name("type", m["type"])
        s.append(
            f"    {{{eff}, {m['power']}, {typ}, {m['accuracy']}, {m['pp']}, "
            f"{m['effect_chance']}}}, /* {data.moves_by_id[mid - 1]} */"
        )
    s.append("};")
    return "\n".join(s) + "\n"


def packed_names(data, names, label, count_sym):
    blob, offs = bytearray(), [0]
    for n in names:
        blob += data.asm.encode(n)
        offs.append(len(blob))
    return (
        f"const uint8_t pb_{label}_names[{len(blob)}] = {{\n{c_bytes(blob)}\n}};\n\n"
        f"const uint16_t pb_{label}_name_off[{count_sym} + 1] = {{\n"
        + "\n".join(
            "    " + ", ".join(str(o) for o in offs[i : i + 12]) + ","
            for i in range(0, len(offs), 12)
        )
        + "\n};\n"
    )


def held_item_names(data):
    """Item names (index item - 1) for items that do something when held, else ""."""
    names = [
        asmlib.unquote(asmlib.split_args(rest)[0])
        for word, rest in legality._statements(data.root / "data/items/names.asm")
        if word == "li"
    ]
    held = [
        data.asm.eval(asmlib.split_args(rest)[1]) & 0xFF
        for word, rest in legality._statements(data.root / "data/items/attributes.asm")
        if word == "item_attribute"
    ]
    species_items = {data.asm.sym[n] for n in boss_items.SPECIES_ITEMS}
    return [
        names[i] if held[i] or i + 1 in species_items else ""
        for i in range(gen_battle.ITEM_TABLE_LEN)
    ]


def gen_names(data):
    return (
        header(
            data, "data/pokemon/names.asm, data/moves/names.asm, data/items/names.asm"
        )
        + '#include "pb_tables.h"\n\n'
        + packed_names(data, data.species_names, "species", "NUM_POKEMON")
        + "\n"
        + packed_names(data, data.move_names, "move", "NUM_ATTACKS")
        + "\n"
        + packed_names(data, held_item_names(data), "item", "PB_ITEM_NAMES_LEN")
    )


def gen_charmap(data):
    cm = data.asm.charmap()
    to_gb = [0] * 128
    for ch in range(32, 127):
        if chr(ch) in cm:
            to_gb[ch] = cm[chr(ch)]
    to_ascii = ["?"] * 256
    for key, val in cm.items():
        if len(key) == 1 and 32 <= ord(key) < 127 and to_ascii[val] == "?":
            to_ascii[val] = key
    extras = {"♂": "M", "♀": "F", "é": "e", "<DOT>": ".", "<PK>": "P", "<MN>": "M"}
    for key, ch in extras.items():
        to_ascii[cm[key]] = ch
    for key in ("'d", "'l", "'m", "'r", "'s", "'t", "'v"):
        to_ascii[cm[key]] = "'"  # char_encode.c appends the letter
    to_ascii[cm["@"]] = "\0"

    def cchar(c):
        return {"\0": "0", "'": "'\\''", "\\": "'\\\\'"}.get(c, f"'{c}'")

    rows = []
    for i in range(0, 256, 16):
        rows.append("    " + ", ".join(cchar(c) for c in to_ascii[i : i + 16]) + ",")
    return (
        header(data, "constants/charmap.asm") + '#include "pb_tables.h"\n\n'
        f"const uint8_t pb_ascii_to_gb[128] = {{\n{c_bytes(to_gb)}\n}};\n\n"
        "const char pb_gb_to_ascii[256] = {\n" + "\n".join(rows) + "\n};\n"
    )


def gen_growth(data):
    names = [data.const_name("growth", g) for g in range(len(data.growth_rates))]
    body = "\n".join(
        f"    {{{', '.join(str(x) for x in g)}}}, /* {n} */"
        for g, n in zip(data.growth_rates, names)
    )
    return (
        header(data, "data/growth_rates.asm") + '#include "pb_tables.h"\n\n'
        f"const PbGrowthRate pb_growth_rates[NUM_GROWTH_RATES] = {{\n{body}\n}};\n"
    )


def load():
    data = legality.Data()
    data.sha = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=data.root,
        check=True,
        capture_output=True,
        text=True,
    ).stdout.strip()
    a = data.asm

    def names_for(prefix_file, filt):
        out = {}
        for name, v in a.sym.items():
            if a.def_file.get(name) == prefix_file and filt(name) and v not in out:
                out[v] = name
        return out

    groups = {
        "type": names_for(
            "constants/type_constants.asm",
            lambda n: n
            not in (
                "PHYSICAL",
                "SPECIAL",
                "UNUSED_TYPES",
                "UNUSED_TYPES_END",
                "TYPES_END",
                "NUM_TYPES",
            )
            and not n.startswith("POKEDEX"),
        ),
        "effect": names_for(
            "constants/move_effect_constants.asm", lambda n: n.startswith("EFFECT_")
        ),
        "growth": names_for(
            "constants/pokemon_data_constants.asm", lambda n: n.startswith("GROWTH_")
        ),
        "gender": {v & 0xFF: n for n, v in a.sym.items() if n.startswith("GENDER_")},
    }

    def const_name(group, value):
        n = groups[group].get(value)
        if n is None:
            raise SystemExit(f"no {group} constant for value {value}")
        if group == "gender" and value == 0xFF:
            return "0xFF"
        return n

    data.const_name = const_name
    return data


def outputs(data):
    return {
        "pb_const.h": gen_const(data),
        "pb_tables.h": TABLES_H,
        "base_stats.c": gen_base_stats(data),
        "moves.c": gen_moves(data),
        "names.c": gen_names(data),
        "charmap.c": gen_charmap(data),
        "growth.c": gen_growth(data),
        "pb_wram.h": gen_battle.gen_wram(data, lambda what: header(data, what)),
        "pb_battle.h": gen_battle.gen_battle_h(data, lambda what: header(data, what)),
        "battle_tables.c": gen_battle.gen_battle_c(
            data, lambda what: header(data, what)
        ),
    }


def write_or_check(outdir, files, check):
    stale = []
    outdir.mkdir(parents=True, exist_ok=True)
    for name, text in files.items():
        path = outdir / name
        old = path.read_text(encoding="utf-8") if path.exists() else None
        if old != text:
            stale.append(name)
            if not check:
                path.write_text(text, encoding="utf-8", newline="\n")
    return stale


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true", help="fail if outputs are stale")
    args = ap.parse_args()
    data = load()
    if data.asm.errors:
        for e in data.asm.errors:
            print("asm warning:", e, file=sys.stderr)
    stale = write_or_check(OUT, outputs(data), args.check)
    if args.check and stale:
        sys.exit(f"stale generated files: {stale}")
    print(
        ("checked" if args.check else "wrote"),
        len(outputs(data)),
        "files;",
        "stale:" if stale else "no changes",
        *stale,
    )


if __name__ == "__main__":
    main()
